mapper.select:
SELECT policy_version_id AS policyVersionId,store_id AS storeId,warehouse_id AS warehouseId,
  negative_stock_mode AS negativeStockMode,effective_from AS effectiveFrom
FROM inv_stock_policy_version
WHERE tenant_id=#{tenantId} AND store_id=#{storeId} AND warehouse_id=#{warehouseId}
  AND effective_from<=#{effectiveAt}
ORDER BY effective_from DESC,policy_version_id DESC LIMIT 1

mapper.update:
UPDATE inv_stock_command SET status='APPLIED',affected_lines=#{affectedLines},
  negative_alert=#{negativeAlert},applied_at=#{appliedAt}
WHERE tenant_id=#{tenantId} AND source_event_id=#{eventId} AND status='PROCESSING'

UPDATE inv_stock_balance SET on_hand_quantity=#{onHandQuantity},last_ledger_sequence=#{lastLedgerSequence},
  record_version=record_version+1,updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND stock_dimension_key=#{dimensionKey} AND record_version=#{expectedVersion}

UPDATE inv_stock_balance SET on_hand_quantity=#{ledgerQuantity},last_ledger_sequence=#{ledgerSequence},
  record_version=record_version+1,updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND stock_dimension_key=#{dimensionKey} AND record_version=#{expectedVersion}

mapper.select:
SELECT COALESCE(SUM(quantity_delta),0) AS ledgerQuantity,COUNT(*) AS ledgerCount,
  COALESCE(MAX(ledger_sequence),0) AS lastLedgerSequence
FROM inv_stock_ledger WHERE tenant_id=#{tenantId} AND stock_dimension_key=#{dimensionKey}
